function speakRobot(text){if(muted){toast('הצליל כבוי. אפשר להפעיל אותו בכפתור הצליל.');return;}if(!globalThis.speechSynthesis||!globalThis.SpeechSynthesisUtterance){toast('אין קול זמין במכשיר. אפשר לקרוא את דברי הרובוט.');return;}if(speechSynthesis.speaking){speechSynthesis.cancel();return;}const voices=speechSynthesis.getVoices().filter(v=>/^he(?:-|$)/i.test(v.lang));const voice=voices.find(v=>v.default)||voices[0];if(!voice){toast('לא נמצא קול בעברית במכשיר. הסיפור מופיע בכתוביות.');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.voice=voice;utterance.lang='he-IL';utterance.rate=.9;utterance.pitch=.75;utterance.volume=.65;tone(155,.16,.025,'sine',0,110);speechSynthesis.speak(utterance);}
