let introSpeechId=0;
function speakIntro(text){const id=++introSpeechId;prologue?.setSpeaker('');const speaker=(text.match(/^(נועה|אמיר|מאיה|יואב|רובוט):/)||[])[1]||'';globalThis.speechSynthesis?.cancel();$('intro-line').hidden=false;$('intro-line').textContent=text;const synth=globalThis.speechSynthesis;if(muted||!synth||!globalThis.SpeechSynthesisUtterance)return;const voices=synth.getVoices().filter(v=>/^he(?:-|$)/i.test(v.lang));const voice=voices.find(v=>v.default)||voices[0];if(!voice)return;const utterance=new SpeechSynthesisUtterance(text.replace(/^[^:]{1,20}:\s*/,''));utterance.voice=voice;utterance.lang='he-IL';utterance.rate=.94;utterance.pitch=text.startsWith('רובוט:')?.82:1;utterance.volume=.62;utterance.onstart=()=>{if(id===introSpeechId){$('intro-line').hidden=true;prologue?.setSpeaker(speaker);}};utterance.onend=()=>{if(id===introSpeechId)prologue?.setSpeaker('');};utterance.onerror=()=>{if(id===introSpeechId){prologue?.setSpeaker('');$('intro-line').hidden=false;$('intro-line').textContent=text;}};synth.speak(utterance);}
let prologue=null;function start(){closeModal();initAudio();state='intro';keys={};yaw=0;pitch=0;for(const id of ['menu','scene-label','menu-footer','hud','pause'])$(id).hidden=true;document.body.classList.add('playing');$('intro').hidden=false;$('intro-fade').style.opacity=0;$('intro-line').hidden=false;$('intro-line').textContent='השעון מצלצל. יום חדש מתחיל.';$('touch').hidden=!mobile;prologue=createPrologue({done:()=>{introSpeechId++;globalThis.speechSynthesis?.cancel();prologue=null;startEscape();toast('הגעת לבית העכביש. הפנס אצלך — מצא גרזן וברח!');},say:speakIntro,stopSpeech:stopIntroSpeech,onDrive:setCarAudio,sound:()=>tone(260,.1,.035)});requestControl();}$('intro-skip').onclick=()=>prologue?.finish();
function startEscape(){foundEvidence.clear();liftPuzzle.reset();liftWing.reset();liftTravel=null;$('lift-ride').hidden=true;globalThis.speechSynthesis?.cancel();robotRoom.reset();hasPower=false;robotTold=false;robotDoorUntil=0;robotPress=0;roomOne.reset();roomTrapped=false;roomKey=false;roomSolved=false;roomEntry=null;if(pickupEffect){camera.remove(pickupEffect.object);pickupEffect=null;}hasKey=false;goldKey.visible=true;basementUnlocked=false;basementDoor.visible=true;basementDoorSign.visible=true;basementLock.top=3;world=makeWorld(colliders);hasFlashlight=true;torchPickup.visible=false;secretLibrary.reset();secretTravel=null;hasJournal=false;basement.reset();hauntedTV.reset();ambientWait=15;$('hide-view').hidden=true;surfaceClimb.reset();climbState=null;jumpscare=createJumpscare();spider.animate(0,0);initAudio();runCount++;state='playing';closeModal();keys={};touchVec={x:0,y:0};hasAxe=false;hits=0;stamina=100;swing=0;elapsed=0;yaw=0;pitch=0;hidden=false;brain=createBrain(patrolPoints);aiStatus={mode:'sleep',notice:0};soundEvents=[];runNoiseTick=0;path=[];pathTick=0;stepTick=0;spiderStep=0;toyTriggered=false;caughtTime=0;player.set(0,1.65,10.5);spider.g.position.set(-8*HOUSE_WIDTH_SCALE,0,-9);spider.g.rotation.set(0,0,0);boards.forEach(b=>b.visible=true);exit.visible=true;let spawn=axeSpawns[Math.floor(Math.random()*axeSpawns.length)];axeFloor=spawn[2]??0;axePickup.position.set(spawn[0],axeFloor+.10,spawn[1]);axePickup.rotation.set(Math.PI/2,0,.45);axePickup.visible=true;axeGlow.position.set(spawn[0],axeFloor+.65,spawn[1]);axeGlow.visible=true;heldAxe.visible=false;lightOn=true;flash.visible=true;$('caught-fx').style.opacity=0;for(let id of ['menu','scene-label','menu-footer'])$(id).hidden=true;$('hud').hidden=false;$('pause').hidden=false;$('touch').hidden=!mobile;document.body.classList.add('playing');$('objective').textContent='מצא את הגרזן';$('subobjective').textContent='הפנס אצלך · F להפעלה וכיבוי · B לתיק. חפש גרזן בחדרים.';$('inventory').innerHTML='<span>אין גרזן</span>';requestControl();toast('מצא גרזן. בארונות אפשר להתחבא. אל תרוץ בלי סיבה.');}
function pause(){if(state==='intro'){state='intro-paused';setCarAudio(false);globalThis.speechSynthesis?.pause();keys={};touchVec={x:0,y:0};document.exitPointerLock?.();modal('הפתיחה מושהית','קח רגע','<p>אפשר להמשיך כשתהיה מוכן.</p>','המשך',()=>{closeModal();state='intro';if(prologue?.phase==='drive')setCarAudio(true);globalThis.speechSynthesis?.resume();requestControl();});return;}if(state!=='playing')return;state='paused';keys={};touchVec={x:0,y:0};document.exitPointerLock?.();$('touch').hidden=true;modal('קח נשימה','העכביש מחכה.',`<p>המשחק מושהה. הזמן והעכביש נעצרו.</p><p>טיפ: ריצה מושכת אותו. היכנס לארון לפני שהוא רואה אותך.</p>`,'חזרה לבית',()=>{state='playing';closeModal();$('touch').hidden=!mobile;requestControl();},true);}
function menu(){setCarAudio(false);liftTravel=null;$('lift-ride').hidden=true;globalThis.speechSynthesis?.cancel();goldKey.visible=false;if(pickupEffect){camera.remove(pickupEffect.object);pickupEffect=null;}torchPickup.visible=false;secretLibrary.reset();secretTravel=null;$('caught-fx').style.opacity=0;basement.reset();hauntedTV.reset();$('hide-view').hidden=true;surfaceClimb.reset();climbState=null;spider.animate(0,0);state='menu';document.exitPointerLock?.();closeModal();$('hud').hidden=true;$('pause').hidden=true;$('touch').hidden=true;for(let id of ['menu','scene-label','menu-footer'])$(id).hidden=false;document.body.classList.remove('playing');heldAxe.visible=false;axePickup.visible=false;axeGlow.visible=false;$('caught-fx').style.opacity=0;spider.g.position.set(-.6,0,-1);spider.g.rotation.y=-.25;updateBest();}
function lose(){if(state!=='playing')return;state='caught';caughtTime=0;bitePlayed=false;catchOrigin.copy(camera.position);catchDirection.set(player.x-spider.g.position.x,0,player.z-spider.g.position.z);if(catchDirection.lengthSq()<.001)catchDirection.set(0,0,-1);catchDirection.normalize();keys={};touchVec={x:0,y:0};heldAxe.visible=false;document.exitPointerLock?.();$('touch').hidden=true;$('pause').hidden=true;$('prompt').textContent='אוי לא… הוא מרים אותך!';$('caught-fx').style.opacity=0;tone(110,.55,.14,'sawtooth',0,62);noise(.3,.12,700);}
function finishCapture(){state='lost';$('prompt').textContent='';modal('נתפסת / נסה שוב','זאת לא הייתה נשיקת לילה טוב.',`<p>העכביש הרים אותך ונתן נשיכה. בפעם הבאה כדאי לשמור מרחק מהניבים!</p><div class="result-stat">${time(elapsed)}</div><p>טיפ: התחבא בארון או פנה מעבר לפינה כדי לצאת מטווח הראייה שלו.</p>`,'עוד ניסיון',start,true);}
function win(){state='won';document.exitPointerLock?.();exit.visible=false;$('touch').hidden=true;let best=bestRead(),record=!best||elapsed<best;if(record){try{localStorage.setItem('spider-house-best-'+difficulty,String(elapsed));}catch{}}tone(440,.3,.15);setTimeout(()=>tone(660,.3,.12),180);setTimeout(()=>tone(880,.6,.1),360);modal('ברחת / העכביש נשאר בבית','בחוץ. סוף סוף.',`<p>מצאת גרזן, שברת ארבעה קרשים וברחת מבעל הבית הכי שעיר בעיר.</p><div class="result-stat">${time(elapsed)}</div><p>${record?'שיא אישי חדש!':'השיא שלך: '+time(best)} · ${['קל','בינוני','קשה מאוד'][['easy','normal','hard'].indexOf(difficulty)]}</p><p>אפשר לנסות שוב: הגרזן יתחבא במקום אחר.</p>`,'עוד לילה אחד',start,true);}
