function confirmMenu(){const saved={kicker:$('modal-kicker').textContent,title:$('modal-title').textContent,body:$('modal-body').innerHTML,action:$('modal-action').textContent,callback:$('modal-action').onclick};const canResume=state==='paused'||state==='intro-paused';modal('יציאה מהמשחק','לצאת לתפריט?','<p>אפשר לחזור לבית ולהמשיך מהמקום שבו עצרת. יציאה לתפריט תסיים את הניסיון הנוכחי.</p><button id="confirm-menu-exit" class="outline">לצאת לתפריט</button>',canResume?'לחזור לבית ולהמשיך':'לחזור למסך הקודם',()=>{if(canResume)saved.callback();else modal(saved.kicker,saved.title,saved.body,saved.action,saved.callback,true);});$('confirm-menu-exit').onclick=()=>{if(prologue){$('intro').hidden=true;prologue=null;}menu();};}

$('help').onclick=()=>modal('מדריך הישרדות / 30 שניות','תעשה פחות רעש.',`<p>חפש את הגרזן המוסתר בחדרים, במעבדת הניסויים ובמרתף. הכניסה למרתף נמצאת בספרייה. חזור לדלת עם השלט הירוק ושבור ארבעה קרשים. כל מכה מזמינה אורח.</p><div class="help-row"><b>W A S D</b><span>תנועה · עכבר כדי להביט</span></div><div class="help-row"><b>E</b><span>לקחת גרזן, להיכנס לארון ולשבור קרש</span></div><div class="help-row"><b>SHIFT</b><span>ריצה — מהירה, אבל רועשת</span></div><div class="help-row"><b>F / ESC</b><span>פנס / השהיה</span></div><p>העכביש רואה קדימה. קירות חוסמים אותו. אם תיעלם מהעין, הוא יחפש במקום האחרון שראה אותך ואז יחזור לשוטט. ריצה ומכות בדלת מושכות אותו למקום הרעש.</p><p>בטלפון: ג'ויסטיק משמאל, מבט בגרירה מימין וכפתורי פעולה. אפשר לשחק גם בלי קול: מד הסכנה מזהיר כשהעכביש קרוב.</p>`,'אני מוכן',closeModal);
for(let b of document.querySelectorAll('[data-diff]'))b.onclick=()=>{difficulty=b.dataset.diff;document.querySelectorAll('[data-diff]').forEach(n=>{n.classList.toggle('selected',n===b);n.setAttribute('aria-pressed',String(n===b));});$('difficulty-note').textContent={easy:'קל: העכביש איטי ושומע פחות. 18 שניות להתארגן.',normal:'בינוני: מהירות ושמיעה רגילות. 12 שניות להתארגן.',hard:'קשה מאוד: העכביש מהיר ושומע מרחוק. 7 שניות להתארגן.'}[difficulty];updateBest();};
